WITH s(slug, section_key, name, ord, eyebrow, heading, description, btn, btnurl, btn2, btn2url, items) AS (
  VALUES
  ('about-us','hero','Hero Section',1,'About J1 Autoland','Driven By Quality. Built On Trust.','An independent dealership where every vehicle is chosen, prepared and described the way we''d want it done for ourselves.','Explore Our Stock','/stocklist',NULL,NULL,'[]'::jsonb),
  ('about-us','stats','Statistics',2,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'[{"value":100,"suffix":"+","label":"Vehicles in stock"},{"value":500,"suffix":"+","label":"Happy customers"},{"value":5,"suffix":"-Star","label":"Rated service"},{"value":165,"suffix":"-Point","label":"Quality checked"}]'::jsonb),
  ('about-us','story','Our Story',3,'Our story','Built one honest handover at a time','J1 Autoland started with a handful of carefully chosen cars and a simple belief: buying a used vehicle should feel as good as driving one. Today we hold over 100 vehicles at our Birmingham site, and the approach hasn''t changed — we only sell cars we would happily put a member of our own family in.',NULL,NULL,NULL,NULL,'[{"title":"Our mission","text":"To make buying, financing and part-exchanging a car straightforward, transparent and genuinely enjoyable — with the full condition of every vehicle on the table before anyone signs anything."}]'::jsonb),
  ('about-us','commitment','Our Commitment',4,'Our commitment','Prepared properly, priced fairly, backed afterwards','Preparation happens in our own workshop, pricing is checked daily against live market data, and support continues long after you drive away. If something isn''t right, we fix it — that''s the whole commitment.',NULL,NULL,NULL,NULL,'["165-point mechanical inspection","Full HPI and mileage verification","Fresh MOT and service where due","12 months'' warranty as standard","Nationwide delivery available","Aftercare from a named advisor"]'::jsonb),
  ('about-us','why','Why Choose Us',5,'Why choose us','Why customers choose J1 Autoland',NULL,NULL,NULL,NULL,NULL,'[{"title":"Quality Vehicles","text":"Every car passes a 165-point inspection, full history check and workshop preparation before it goes on sale."},{"title":"Transparent Pricing","text":"The price you see is the price you pay. No admin fees, no preparation charges, no surprises at handover."},{"title":"Flexible Finance","text":"PCP, HP and lease purchase from a panel of 22 lenders, with soft-search quotes that don''t mark your credit file."},{"title":"Part Exchange","text":"A fair, same-day offer on your current car that can go straight into your deposit."},{"title":"Customer Support","text":"A named contact from first enquiry through to years after handover — not a call centre queue."},{"title":"Warranty Options","text":"12 months'' cover as standard with extended plans and nationwide repairs available."}]'::jsonb),
  ('about-us','cta','Call To Action',6,NULL,'Ready to find your next car?','Browse the current stock list or come and see us at our showroom.','Explore Our Stock','/stocklist','Find Us','/find-us','[]'::jsonb),
  ('contact','hero','Hero Section',1,'Get in touch','We''re here seven days a week','Whether you want a walkaround video, a finance quote or directions to the showroom — just ask.',NULL,NULL,NULL,NULL,'[]'::jsonb),
  ('contact','details','Contact Details',2,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'[{"title":"Call the showroom","text":"+44(0)7483891595","url":"tel:+447483891595"},{"title":"Email us","text":"J1autoland26@gmail.com","url":"mailto:J1autoland26@gmail.com"},{"title":"Visit us","text":"31 York Road, Birmingham, B21 9EB"}]'::jsonb),
  ('contact','form','Enquiry Form',3,NULL,'Send us a message',NULL,'Send message',NULL,NULL,NULL,'[]'::jsonb),
  ('contact','hours','Opening Hours',4,NULL,'Opening hours',NULL,NULL,NULL,NULL,NULL,'[{"title":"Monday – Friday","text":"09:00 – 18:30"},{"title":"Saturday","text":"09:00 – 17:00"},{"title":"Sunday","text":"11:00 – 16:00"},{"title":"Bank Holidays","text":"By appointment"}]'::jsonb),
  ('contact','map','Map',5,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'[]'::jsonb),
  ('faq','hero','Hero Section',1,'Help centre','Frequently asked questions','Everything about buying, financing, warranty and delivery — in plain English.',NULL,NULL,NULL,NULL,'[]'::jsonb),
  ('faq','faq','Questions',2,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'[{"title":"Can I view a car before buying?","text":"Yes — our Birmingham showroom is open seven days a week, and appointments guarantee the car is unlocked, charged and ready."},{"title":"Do you sell nationally?","text":"We deliver anywhere in mainland UK, usually within 72 hours of the sale completing."},{"title":"Can I reserve a car online?","text":"Yes. A £199 refundable deposit holds any vehicle for seven days."},{"title":"What rates do you offer?","text":"Rates start at 6.9% APR representative and depend on your credit profile, deposit and term."},{"title":"Will applying hurt my credit score?","text":"No. Our quotes use a soft search that is invisible to other lenders."},{"title":"Can I overpay or settle early?","text":"Yes, with no early repayment penalties on any agreement we arrange."},{"title":"What payment methods do you accept?","text":"Bank transfer, debit card and finance. Card payments are capped at £5,000."},{"title":"Is my deposit refundable?","text":"Fully refundable within seven days if you change your mind."},{"title":"Are there admin fees?","text":"None. The price you see is the price you pay."},{"title":"What''s included?","text":"A 12-month comprehensive warranty covering engine, transmission, electrics and more, with unlimited claims."},{"title":"Can I extend it?","text":"Yes — 24 and 36 month extensions are available at the point of sale."},{"title":"Where can I get work done?","text":"At any VAT-registered garage in the UK, or at our own workshop."},{"title":"How long does delivery take?","text":"Typically 48–72 hours after funds clear and paperwork is signed."},{"title":"Is delivery free?","text":"Free on vehicles over £30,000. Below that it''s a flat £149 anywhere in mainland UK."},{"title":"Can I return the car?","text":"Yes — a 14-day money-back guarantee applies to all distance sales, up to 500 miles."},{"title":"Do you take part exchange?","text":"On every car we sell. Get an estimate on our part exchange page in under a minute."},{"title":"What if I still owe finance?","text":"We settle the outstanding balance directly with your lender and offset any equity."},{"title":"How long is a valuation valid?","text":"Seven days or 250 additional miles, whichever comes first."}]'::jsonb),
  ('faq','cta','CTA Section',3,NULL,'Still have a question?','Our team answers calls and messages seven days a week.','Contact us','/contact',NULL,NULL,'[]'::jsonb),
  ('finance','hero','Hero Section',1,'Finance','Make Your Next Car More Affordable','Explore flexible finance options designed around your budget. FCA-registered credit broker working with 22 lenders — soft-search quotes with no impact on your credit score.','Calculate Finance','#calculator','Apply For Finance','#apply','[]'::jsonb),
  ('finance','products','How Finance Works',2,'How finance works','Four simple steps',NULL,NULL,NULL,NULL,NULL,'[{"title":"Choose Your Vehicle","text":"Pick any car from our stock list — finance is available across the range."},{"title":"Calculate Your Payments","text":"Set your deposit and term to see an accurate monthly figure."},{"title":"Apply For Finance","text":"One short soft-search application, checked across 22 lenders."},{"title":"Drive Away","text":"Sign digitally and collect, or we deliver nationwide to your door."}]'::jsonb),
  ('finance','calculator','Payment Calculator',3,NULL,'Monthly payment estimator','Representative example based on 6.9% APR. Figures are indicative and subject to status.',NULL,NULL,NULL,NULL,'[]'::jsonb),
  ('finance','why','Why Finance With Us',4,NULL,'Why finance with J1 Autoland',NULL,NULL,NULL,NULL,NULL,'[{"title":"22 lenders, one form","text":"We shop your application across the market to find the sharpest rate."},{"title":"No credit footprint","text":"Soft-search quotes are invisible to other lenders."},{"title":"Flexible terms","text":"12 to 60 months, with or without a deposit."},{"title":"Settle any time","text":"No early repayment penalties on any agreement."}]'::jsonb),
  ('finance','faq','Finance FAQ',5,NULL,'Finance questions',NULL,NULL,NULL,NULL,NULL,'[{"title":"Will a quote affect my credit score?","text":"No. We run a soft search to give you an accurate quote, which is invisible to other lenders and leaves no footprint."},{"title":"What deposit do I need?","text":"None. We offer zero-deposit agreements, though a larger deposit reduces your monthly payment and total interest."},{"title":"Can I settle the agreement early?","text":"Yes. Every agreement we arrange allows early settlement with no penalty charges."},{"title":"Do you accept part exchange as a deposit?","text":"Absolutely. Any equity in your current car can be used as all or part of your deposit."},{"title":"Can I get finance with poor credit?","text":"We work with 22 lenders including specialists in adverse credit, so we can usually find an option."}]'::jsonb),
  ('finance','cta','Finance CTA',6,NULL,NULL,NULL,'Find a car to finance','/stocklist',NULL,NULL,'[]'::jsonb),
  ('find-us','hero','Hero Section',1,'Visit Our Showroom','Visit J1 Autoland','Come and view our latest vehicles and speak with our team.','Call Us',NULL,'WhatsApp',NULL,'[]'::jsonb),
  ('find-us','details','Location Details',2,NULL,'Address','Free customer parking on site. Five minutes from the A41 in Birmingham.',NULL,NULL,NULL,NULL,'[]'::jsonb),
  ('find-us','hours','Opening Hours',3,NULL,'Opening hours',NULL,NULL,NULL,NULL,NULL,'[{"title":"Monday","text":"09:00 – 18:30"},{"title":"Tuesday","text":"09:00 – 18:30"},{"title":"Wednesday","text":"09:00 – 18:30"},{"title":"Thursday","text":"09:00 – 18:30"},{"title":"Friday","text":"09:00 – 18:30"},{"title":"Saturday","text":"09:00 – 17:00"},{"title":"Sunday","text":"11:00 – 16:00"}]'::jsonb),
  ('find-us','cta','Enquiry CTA',4,'Have A Question?','Send us an enquiry','Ask about a specific vehicle, book a viewing or arrange a test drive. We reply to every message within one working hour.','Send Enquiry',NULL,NULL,NULL,'[]'::jsonb),
  ('part-exchange','hero','Hero Section',1,'Part exchange','Trade in, drive out','Use your current car as your deposit. We settle any outstanding finance directly with your lender and handle the DVLA paperwork for you.',NULL,NULL,NULL,NULL,'[]'::jsonb),
  ('part-exchange','benefits','Good To Know',2,NULL,'Good to know',NULL,NULL,NULL,NULL,NULL,'["We settle outstanding finance directly with your lender.","Any equity goes straight towards your new car''s deposit.","No admin fees, ever.","Valuations held for 7 days or 250 miles."]'::jsonb),
  ('reviews','hero','Hero Section',1,'Trusted By Our Customers','What Our Customers Say','Real customers. Real experiences. 4.9 out of 5 from 2,417 verified buyers across Google, Autotrader and our own aftercare surveys.',NULL,NULL,NULL,NULL,'[]'::jsonb),
  ('reviews','intro','Trust Section',2,'Real Customers. Real Experiences.','Every review is left by a verified buyer','We never filter, edit or remove feedback. Our Google profile is updated live with each new handover, so what you read is exactly what our customers wrote.',NULL,NULL,NULL,NULL,'[]'::jsonb),
  ('reviews','cta','CTA Section',3,NULL,NULL,NULL,'Find Your Next Car','/stocklist',NULL,NULL,'[]'::jsonb),
  ('sell-your-car','hero','Hero Section',1,'Sell or part exchange','We''ll buy your car today','Enter your registration for a free, no-obligation valuation. We pay same day by bank transfer, collect free of charge and handle all the paperwork.',NULL,NULL,NULL,NULL,'[]'::jsonb),
  ('sell-your-car','steps','How It Works',2,NULL,'How it works',NULL,NULL,NULL,NULL,NULL,'[{"title":"Send us the details","text":"Registration, mileage and a few photos is all we need."},{"title":"Get your valuation","text":"A real buyer prices your car within two working hours."},{"title":"We collect, you get paid","text":"Free collection nationwide and same-day bank transfer."}]'::jsonb),
  ('services','hero','Hero Section',1,'Our Services','More Than Just A Car Dealership','From finding your next vehicle to keeping it in excellent condition, we''re here to help.','Browse Our Stock','/stocklist',NULL,NULL,'[]'::jsonb),
  ('services','intro','Intro',2,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'[]'::jsonb),
  ('services','services','Service Cards',3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'[{"title":"Vehicle Sales","text":"Over 100 hand-selected vehicles, each inspected, prepared and honestly described.","image":"","url":"/stocklist"},{"title":"Vehicle Sourcing","text":"Tell us the exact specification you want and we''ll find it through our trade network.","image":"","url":"/contact"},{"title":"Finance","text":"PCP, HP and lease purchase from a panel of 22 lenders with soft-search quotes.","image":"","url":"/finance"},{"title":"Part Exchange","text":"Use your current car as your deposit with a same-day, no-obligation offer.","image":"","url":"/part-exchange"},{"title":"Vehicle Valuation","text":"A fair, market-accurate figure for your vehicle within one working hour.","image":"","url":"/valuation"},{"title":"Warranty","text":"12 months'' cover as standard with extended protection options available.","image":"","url":"/warranty"},{"title":"After-Sales Support","text":"A named contact after handover for servicing, claims and any question at all.","image":"","url":"/find-us"},{"title":"Vehicle Preparation","text":"165-point inspection, full valet, fresh MOT and service before every handover.","image":"","url":"/about-us"}]'::jsonb),
  ('services','process','Process Steps',4,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'[{"title":"Sourcing done properly","text":"If it isn''t on the forecourt, we''ll find it. Our buyers work auctions, main-dealer part exchanges and private collections daily, so the exact colour, spec and mileage you want is usually only days away."},{"title":"Prepared to a standard you can see","text":"Every vehicle goes through our workshop before it reaches the display floor: mechanical inspection, brake and tyre assessment, diagnostics, paint correction and a full valet inside and out."}]'::jsonb),
  ('services','cta','Call To Action',5,NULL,'Need Help Finding The Right Vehicle?','Our team will match your budget, mileage and specification to the right car — or source it for you. Call us or send us a message.','Contact Us','/contact',NULL,NULL,'[]'::jsonb),
  ('stocklist','hero','Hero Section',1,'Our Vehicles','Find Your Next Car','Explore our latest selection of quality vehicles from trusted manufacturers — every car inspected across 165 points, warranted and available with finance or nationwide delivery.',NULL,NULL,NULL,NULL,'[]'::jsonb),
  ('valuation','hero','Hero Section',1,'Vehicle Valuation','What''s Your Car Worth?','Get a valuation for your vehicle and discover how much it could be worth.',NULL,NULL,NULL,NULL,'[]'::jsonb),
  ('valuation','form','Valuation Form',2,NULL,'Your vehicle','No obligation. We''ll never pass your details to a third party.','Request Valuation',NULL,NULL,NULL,'[]'::jsonb),
  ('valuation','steps','Why Value Your Car With Us',3,NULL,'Why Value Your Car With Us?',NULL,NULL,NULL,NULL,NULL,'[{"title":"Fair Valuation","text":"Live market data, auction results and retail demand — not a lowball guess."},{"title":"Fast Response","text":"A real figure from a real buyer within one working hour, seven days a week."},{"title":"Simple Process","text":"One short form, no haggling, no obligation and no admin fees."},{"title":"Part Exchange Available","text":"Put every penny of your valuation straight into your next car."}]'::jsonb),
  ('valuation','cta','Talk It Through CTA',4,NULL,'Prefer to talk it through?','Our buying team is on the phone seven days a week.',NULL,NULL,'Contact Our Team','/contact','[]'::jsonb),
  ('warranty','hero','Hero Section',1,'Warranty & Protection','Drive With Confidence','Every vehicle deserves peace of mind. Explore our warranty options and vehicle protection.','Speak To Our Team','/contact',NULL,NULL,'[]'::jsonb),
  ('warranty','plans','Benefit Cards',2,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'[{"title":"Warranty Protection","text":"12 months'' comprehensive cover included with every vehicle we sell.","price":""},{"title":"Vehicle Support","text":"Repairs at any VAT-registered garage in the UK — no approved-network limits.","price":""},{"title":"Peace Of Mind","text":"Parts and labour paid directly to the garage, so there''s nothing to reclaim.","price":""},{"title":"Professional Assistance","text":"A named advisor handles your claim from first call to completed repair.","price":""}]'::jsonb),
  ('warranty','covered','What''s Covered',3,'The detail','What your cover includes',NULL,NULL,NULL,NULL,NULL,'["Engine and cylinder head","Gearbox, clutch and transmission","Turbocharger and fuel system","Drivetrain, axles and differentials","Braking and steering components","Suspension and wheel bearings","Cooling and heating systems","Electrics, ECUs and sensors","Air conditioning components","Hybrid and EV drive units"]'::jsonb),
  ('warranty','cta','Still Have A Question CTA',4,NULL,'Still have a question?','Our warranty team will talk you through exactly what''s covered on the car you''re considering.','Speak To Our Team','/contact','Browse Our Stock','/stocklist','[]'::jsonb)
