INSERT INTO public.page_sections (page_id, section_key, name, sort_order, eyebrow, heading, description, button_text, button_url, secondary_button_text, secondary_button_url, items, settings, status)
SELECT p.id, s.section_key, s.name, s.ord, s.eyebrow, s.heading, s.description, s.btn, s.btnurl, s.btn2, s.btn2url, s.items, '{}'::jsonb, 'published'
FROM s JOIN public.pages p ON p.slug = s.slug
ON CONFLICT (page_id, section_key) DO NOTHING;